      '.lg-btn:hover{background:#0077ed}',
      '.lg-btn:disabled{opacity:.5;cursor:default}',
      '.lg-btn.ghost{background:#f5f5f7;color:#3a3a3c;font-weight:500}',
      '.lg-btn.ghost:hover{background:#e8e8ed}',
      '.lg-btn.sm{height:36px;font-size:13px;flex:1}',
      '.lg-msg{font-size:12.5px;min-height:19px;margin:0 0 8px;line-height:1.5}',
      '.lg-msg.err{color:#ff3b30}', '.lg-msg.ok{color:#34c759}', '.lg-msg.info{color:#0071e3}',
      '.lg-tip{font-size:11.5px;color:#aeaeb2;margin-top:6px;line-height:1.6}',
      '.lg-hr{height:1px;background:rgba(0,0,0,.07);margin:16px 0}',
      '.lg-link{color:#0071e3;cursor:pointer;font-size:11.5px}',
      '.lg-link:hover{text-decoration:underline}',
      '.lg-row{display:flex;gap:8px;margin-top:10px}',
      '.lg-me{display:flex;align-items:center;gap:12px;margin-bottom:4px}',
      '.lg-av{width:72px;height:72px;border-radius:50%;background:linear-gradient(135deg,#0071e3,#34c759);',
      'color:#fff;display:flex;align-items:center;justify-content:center;flex:none;',
      'overflow:hidden;cursor:pointer;position:relative;border:0;padding:0;transition:transform .15s}',
      '.lg-av:active{transform:scale(.94)}',
      /* 图片头像缩到与 emoji 完全相同的尺寸（46px），居中放在 72px 框里 */
      '.lg-av img{width:46px!important;height:46px!important;max-width:46px!important;max-height:46px!important;',
